#!/usr/bin/env python3
import sys

def to_base36(num):
    """Convert an integer to base36 string."""
    chars = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    if num == 0:
        return '0'
    result = []
    while num > 0:
        result.append(chars[num % 36])
        num //= 36
    return ''.join(reversed(result))

def from_base36(s):
    """Convert a base36 string to integer."""
    return int(s, 36)

def main():
    with open('ids.txt', 'r') as f:
        lines = f.readlines()

    # Find the last non-empty line that contains an ID
    last_id = None
    for line in reversed(lines):
        line = line.strip()
        if line and '\t' in line:
            parts = line.split('\t')
            if len(parts) >= 2:
                last_id = parts[1]
                break

    if last_id is None:
        print("ORD-0000")
        return

    # Extract the four-character code after 'ORD-'
    prefix = 'ORD-'
    if not last_id.startswith(prefix):
        print(f"Error: unexpected ID format: {last_id}", file=sys.stderr)
        sys.exit(1)

    code = last_id[len(prefix):]
    num = from_base36(code)
    next_num = num + 1
    next_code = to_base36(next_num).zfill(4)
    print(f"{prefix}{next_code}")

if __name__ == '__main__':
    main()

