#!/usr/bin/env python3
"""Rotate app.log entries older than 7 days before AS_OF into archive.log."""

import sys
import os
from datetime import datetime, timezone


def parse_ts(line: str) -> int | None:
    """Extract the leading timestamp from a log line and return Unix seconds."""
    try:
        dt = datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S")
        return int(dt.replace(tzinfo=timezone.utc).timestamp())
    except (ValueError, IndexError):
        return None


def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("AS_OF must be an integer Unix timestamp.", file=sys.stderr)
        sys.exit(1)

    cutoff = as_of - 7 * 86400  # strictly older than 7 days before AS_OF

    log_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "app.log")
    archive_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "archive.log")

    if not os.path.exists(log_path):
        print("app.log not found.", file=sys.stderr)
        sys.exit(1)

    with open(log_path, encoding="utf-8") as f:
        lines = f.readlines()

    keep = []
    archive = []

    for line in lines:
        ts = parse_ts(line)
        if ts is None:
            # If we can't parse, keep it in app.log
            keep.append(line)
        elif ts < cutoff:
            archive.append(line)
        else:
            keep.append(line)

    # Rewrite app.log with entries that should stay
    with open(log_path, "w", encoding="utf-8") as f:
        f.writelines(keep)

    # Append archived entries to archive.log
    if archive:
        with open(archive_path, "a", encoding="utf-8") as f:
            f.writelines(archive)


if __name__ == "__main__":
    main()

